import { AbsoluteFill, getInputProps, Img, staticFile, useCurrentFrame } from "remotion";
import { Boneco, idle, mix } from "./Boneco";
import { FONT, io, k, pop } from "./RumoFora";
import { BRIGHT, BTN, DEEP, INK, RED, type Wd } from "./DesapertoSelfie";
import { PHRASES } from "./legendas";

// Desaperto — VSL da página /desaperto/oferta: 16:9 (1920×1080), 30 fps, ~74 s.
// Roteiro aprovado em morar-fora/docs/desaperto-vsl.md. Voz Lax Whisper com tags (src/voz-v1_tight.wav, 71 s).
// Toca muda em loop na página: legenda queimada palavra a palavra na faixa de baixo (y ≥ 880); o conteúdo vive acima.
// Visual: bonecos P&B com glow do Rumo Fora sobre a tinta do Desaperto; verde para o plano, vermelho para o aperto.
// Capa do player: renderizar um quadro com --props='{"capa":true}' (sem a legenda).
// Telas reais do app em public/desaperto-vsl/ (hoje, reserva, dividas, sos). Sem áudio aqui: mixagem à parte.

export const DV_FPS = 30;
const VO = 0.3;
const VOICE = 71.0;
const END_CARD = VOICE + 0.4; // cartão final depois de "comece hoje"
export const DV_FRAMES = Math.round((END_CARD + VO + 3.2) * DV_FPS);
const v = (s: number) => s + VO;

const DARK = "#07130d";
const TEXT = "#f2f7f4";
const SOFT = "#93ab9e";
const FAINT = "#5d7568";
const CARD = "rgba(255,255,255,0.05)";
const LINE = "rgba(255,255,255,0.13)";
const RED_GLOW = "rgba(224,75,75,0.45)";
const tela = (f: string) => staticFile(`desaperto-vsl/${f}`);

// ───────── base ─────────
const Bg: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: DARK }}>
    <AbsoluteFill style={{ background: `radial-gradient(1100px 700px at ${50 + Math.sin(t * 0.3) * 18}% -160px, rgba(31,157,85,0.22), transparent 70%)` }} />
    <AbsoluteFill style={{ background: `radial-gradient(900px 600px at ${50 - Math.sin(t * 0.25) * 25}% 1180px, rgba(16,36,26,0.9), transparent 70%)` }} />
    <AbsoluteFill style={{ backgroundImage: "radial-gradient(rgba(255,255,255,0.07) 1.4px, transparent 1.4px)", backgroundSize: "36px 36px", backgroundPosition: `${(-t * 14).toFixed(1)}px ${(Math.sin(t * 0.4) * 10).toFixed(1)}px` }} />
  </AbsoluteFill>
);

// cena: entra e sai com desfoque, drift lento e contínuo (sem pulsar)
const Scene: React.FC<{ t: number; a: number; b: number; children: React.ReactNode }> = ({ t, a, b, children }) => {
  const o = io(t, v(a) - 0.15, 0.3) * (1 - io(t, v(b) - 0.15, 0.3));
  if (o <= 0.001) return null;
  const el = Math.max(0, t - v(a));
  const drift = 1 + 0.035 * Math.min(1, el / 8);
  return (
    <AbsoluteFill style={{ opacity: o, filter: o < 1 ? `blur(${((1 - o) * 12).toFixed(1)}px)` : undefined, transform: `scale(${((0.96 + 0.04 * o) * drift).toFixed(4)})` }}>
      {children}
    </AbsoluteFill>
  );
};

const Txt: React.FC<{ t: number; at: number; size: number; color?: string; weight?: number; style?: React.CSSProperties; children: React.ReactNode }> = ({ t, at, size, color = TEXT, weight = 600, style, children }) => {
  const e = k(t, v(at) - 0.05, 0.5);
  return (
    <div style={{ fontFamily: FONT, fontWeight: weight, fontSize: size, letterSpacing: "-0.035em", lineHeight: 1.06, color, opacity: k(t, v(at) - 0.05, 0.2), filter: e < 1 ? `blur(${((1 - e) * 8).toFixed(1)}px)` : undefined, transform: `translateY(${((1 - e) * size * 0.3).toFixed(1)}px)`, ...style }}>
      {children}
    </div>
  );
};
const Chip: React.FC<{ t: number; at: number; bg?: string; color?: string; size?: number; border?: string; children: React.ReactNode }> = ({ t, at, bg = CARD, color = TEXT, size = 30, border = LINE, children }) => (
  <div style={{ display: "inline-flex", alignItems: "center", gap: size * 0.4, padding: `${size * 0.36}px ${size * 0.75}px`, borderRadius: 999, background: bg, border: `1px solid ${border}`, color, fontFamily: FONT, fontWeight: 600, fontSize: size, opacity: k(t, v(at), 0.25), transform: `scale(${(0.7 + 0.3 * pop(t, v(at), 0.5)).toFixed(3)})` }}>{children}</div>
);
const Logo: React.FC<{ size: number }> = ({ size }) => (
  <div style={{ display: "inline-flex", alignItems: "center", gap: size * 0.32 }}>
    <div style={{ width: size, height: size, borderRadius: size * 0.32, background: DEEP, border: "1px solid rgba(63,220,126,0.35)", display: "grid", placeItems: "center", boxShadow: "0 0 30px rgba(63,220,126,0.25)" }}>
      <svg viewBox="0 0 24 24" width={size * 0.6} height={size * 0.6} fill="none" stroke={BRIGHT} strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round"><path d="M5 9c2.5-3 11.5-3 14 0M5 15c2.5 3 11.5 3 14 0" /><path d="M12 6v12" /></svg>
    </div>
    <span style={{ fontFamily: FONT, fontSize: size * 0.62, letterSpacing: "-0.03em", color: TEXT }}><b style={{ fontWeight: 600 }}>des</b>aperto</span>
  </div>
);
// chão de luz em 16:9
const Floor: React.FC<{ x: number; y: number; w: number; o?: number }> = ({ x, y, w, o = 1 }) => (
  <div style={{ position: "absolute", left: x - w / 2, width: w, top: y, height: 2, opacity: o, background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.5) 30%, rgba(255,255,255,0.5) 70%, transparent)", boxShadow: "0 0 24px 2px rgba(255,255,255,0.15)" }}>
    <div style={{ position: "absolute", left: 0, right: 0, top: 2, height: 120, background: "linear-gradient(180deg, rgba(255,255,255,0.05), transparent)" }} />
  </div>
);

// celular com tela real do app (ou placeholder enquanto a tela não existe)
const Phone: React.FC<{ t: number; at: number; src: string; w: number; tilt?: number; dim?: number; children?: React.ReactNode }> = ({ t, at, src, w, tilt = 0, dim = 0, children }) => {
  const e = k(t, v(at) - 0.1, 0.7);
  const h = w * 2.164;
  return (
    <div style={{ position: "relative", width: w, height: h, borderRadius: w * 0.14, padding: w * 0.03, background: "#121a16", boxShadow: `0 0 0 2px rgba(255,255,255,0.12), 0 0 60px rgba(63,220,126,${(0.12 * (1 - dim)).toFixed(2)}), 0 50px 100px -40px rgba(0,0,0,0.95)`, opacity: k(t, v(at) - 0.1, 0.3) * (1 - 0.55 * dim), transform: `translateY(${((1 - e) * 120).toFixed(1)}px) rotate(${(tilt * (1 + (1 - e))).toFixed(2)}deg) scale(${(0.92 + 0.08 * e).toFixed(3)})` }}>
      <div style={{ position: "relative", width: "100%", height: "100%", borderRadius: w * 0.115, overflow: "hidden", background: "#f5faf7" }}>
        <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "50% 0%" }} />
        {children}
      </div>
    </div>
  );
};

// ───────── legenda queimada (faixa de baixo) ─────────
const Caption: React.FC<{ t: number }> = ({ t }) => {
  const s = t - VO;
  const i = PHRASES.findIndex((p, j) => s >= p[0][1] - 0.1 && (j === PHRASES.length - 1 || s < PHRASES[j + 1][0][1] - 0.1));
  if (i < 0 || s > VOICE + 0.3) return null;
  const p = PHRASES[i] as Wd[];
  return (
    <div style={{ position: "absolute", left: 160, right: 160, top: 920, display: "flex", justifyContent: "center" }}>
      <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", columnGap: 16, padding: "14px 34px", borderRadius: 26, background: "rgba(4,12,8,0.72)", border: "1px solid rgba(255,255,255,0.08)" }}>
        {p.map(([w, at, em], j) => {
          const e = k(s, at - 0.06, 0.22);
          const next = p[j + 1]?.[1] ?? 99;
          const live = s >= at - 0.04 && s < next;
          return (
            <span key={j} style={{ fontFamily: FONT, fontWeight: 700, fontSize: 58, letterSpacing: "-0.025em", lineHeight: 1.15, opacity: 0.12 + 0.88 * e, color: em === "r" ? "#ff7b7b" : live || em === "g" ? BRIGHT : TEXT }}>{w}</span>
          );
        })}
      </div>
    </div>
  );
};

// ───────── 1. se sua renda parasse amanhã (0–4 s) ─────────
const Renda: React.FC<{ t: number }> = ({ t }) => {
  const start = v(0.9);
  const torn = Math.max(0, Math.floor((t - start) / 0.32));
  const day = 1 + torn;
  const frac = t > start ? ((t - start) % 0.32) / 0.32 : 0;
  return (
    <AbsoluteFill>
      <div style={{ position: "absolute", left: 0, right: 0, top: 90, textAlign: "center" }}>
        <Txt t={t} at={-0.3} size={84}>Se sua renda parasse amanhã…</Txt>
      </div>
      <Floor x={760} y={800} w={900} o={k(t, v(-0.2), 0.6)} />
      <Boneco id="renda" x={640} y={800} h={430} pose={mix(idle(t, 1), { head: 14, armF: 6, armB: -4 }, io(t, v(1.4), 1.2))} />
      {/* calendário destacável: as folhas vão caindo */}
      <div style={{ position: "absolute", left: 980, top: 300, width: 360, height: 420, opacity: k(t, v(-0.1), 0.4) }}>
        <div style={{ position: "absolute", left: 0, right: 0, top: -54, textAlign: "center", fontFamily: FONT, fontSize: 28, letterSpacing: "0.22em", color: SOFT }}>DIAS SEM RENDA</div>
        <div style={{ position: "absolute", inset: 0, borderRadius: 30, background: "linear-gradient(180deg, #f2f7f4, #cfd9d3)", boxShadow: "0 0 50px rgba(255,255,255,0.14), 0 40px 80px -30px rgba(0,0,0,0.9)" }}>
          <div style={{ height: 92, borderRadius: "30px 30px 0 0", background: RED, display: "grid", placeItems: "center", fontFamily: FONT, fontWeight: 600, fontSize: 34, color: "#fff", letterSpacing: "0.12em" }}>SEM SALÁRIO</div>
          <div style={{ display: "grid", placeItems: "center", height: 328, fontFamily: FONT, fontWeight: 700, fontSize: 200, color: INK, letterSpacing: "-0.06em", fontVariantNumeric: "tabular-nums" }}>{day}</div>
        </div>
        {/* folha caindo */}
        {t > start && (
          <div style={{ position: "absolute", left: 0, right: 0, top: 92, height: 328, borderRadius: "0 0 30px 30px", background: "#e9f0ec", display: "grid", placeItems: "center", fontFamily: FONT, fontWeight: 700, fontSize: 200, color: INK, letterSpacing: "-0.06em", transformOrigin: "50% 0%", transform: `translateY(${(frac * frac * 700).toFixed(1)}px) rotate(${(frac * 28).toFixed(1)}deg)`, opacity: Math.max(0, 1 - frac * 2.2) }}>{day - 1 || ""}</div>
        )}
      </div>
    </AbsoluteFill>
  );
};

// ───────── 2. bolsa e dólar (4–14,5 s) ─────────
const Stat: React.FC<{ t: number; at: number; label: string; value: number; arrow: string }> = ({ t, at, label, value, arrow }) => {
  const n = value * io(t, v(at), 1.0);
  const e = k(t, v(at) - 0.2, 0.6);
  return (
    <div style={{ width: 640, padding: "36px 46px", borderRadius: 40, background: "rgba(224,75,75,0.07)", border: "1px solid rgba(224,75,75,0.35)", boxShadow: `0 0 60px ${RED_GLOW.replace("0.45", "0.12")}`, opacity: k(t, v(at) - 0.2, 0.3), transform: `translateY(${((1 - e) * 60).toFixed(1)}px)` }}>
      <div style={{ fontFamily: FONT, fontSize: 34, color: SOFT, letterSpacing: "0.04em" }}>{label}</div>
      <div style={{ fontFamily: FONT, fontWeight: 700, fontSize: 132, whiteSpace: "nowrap", letterSpacing: "-0.05em", color: RED, lineHeight: 1.05, textShadow: `0 0 40px ${RED_GLOW}`, fontVariantNumeric: "tabular-nums" }}>
        {arrow} {n.toLocaleString("pt-BR", { minimumFractionDigits: 1, maximumFractionDigits: 1 })}%
      </div>
    </div>
  );
};
const Mercado: React.FC<{ t: number }> = ({ t }) => {
  const up = io(t, v(11.0), 0.7);
  const months = ["nov", "dez", "jan", "fev", "mar", "abr"];
  return (
    <AbsoluteFill>
      <div style={{ position: "absolute", left: 0, right: 0, top: 80, textAlign: "center" }}>
        <Txt t={t} at={4.08} size={34} color={SOFT} weight={500} style={{ letterSpacing: "0.18em", textTransform: "uppercase" }}>No dia seguinte à eleição · 26/10/2026</Txt>
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 210 - 70 * up, display: "flex", justifyContent: "center", gap: 60, transform: `scale(${(1 - 0.18 * up).toFixed(3)})`, transformOrigin: "50% 0%" }}>
        <Stat t={t} at={6.12} label="Ibovespa (bolsa)" value={13.9} arrow="↓" />
        <Stat t={t} at={8.82} label="Dólar" value={8.2} arrow="↑" />
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 500 - 50 * up, textAlign: "center", fontFamily: FONT, fontSize: 24, color: FAINT, opacity: k(t, v(6.3), 0.5) }}>Fonte: InfoMoney, 26/10/2026</div>
      {/* os próximos meses: ninguém sabe */}
      <div style={{ position: "absolute", left: 0, right: 0, top: 640, display: "flex", justifyContent: "center", gap: 26 }}>
        {months.map((m, i) => {
          const at = 11.64 + i * 0.22;
          const o = k(t, v(at), 0.4);
          return (
            <div key={m} style={{ width: 170, height: 170, borderRadius: 30, border: `1px solid ${LINE}`, background: CARD, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 6, opacity: o * (0.95 - i * 0.12), filter: `blur(${(i * 1.1).toFixed(1)}px)`, transform: `translateY(${((1 - o) * 40).toFixed(1)}px)` }}>
              <div style={{ fontFamily: FONT, fontSize: 30, color: SOFT, letterSpacing: "0.1em" }}>{m.toUpperCase()}</div>
              <div style={{ fontFamily: FONT, fontSize: 70, fontWeight: 700, color: TEXT, opacity: 0.55 + 0.45 * Math.abs(Math.sin(t * 1.6 + i)) }}>?</div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

// ───────── 3. sem reserva, a crise vai pro cartão (14,5–22,9 s) ─────────
const Cartao: React.FC<{ t: number }> = ({ t }) => {
  const grow = io(t, v(15.5), 6.0);
  const debt = io(t, v(18.6), 0.3);
  const valor = Math.round(820 + 4050 * grow);
  const cardE = k(t, v(14.6), 0.7);
  return (
    <AbsoluteFill>
      <div style={{ position: "absolute", left: 0, right: 0, top: 80, textAlign: "center" }}>
        <Txt t={t} at={14.62} size={72}>Sem reserva, a crise vai pro <span style={{ color: RED }}>cartão</span></Txt>
      </div>
      <Floor x={460} y={820} w={700} o={k(t, v(14.6), 0.5)} />
      <Boneco id="cartao" x={430} y={820} h={420} pose={mix(idle(t, 3), { armF: 68, elbowF: 14, head: 6 }, io(t, v(15.2), 0.8))} />
      {/* cartão */}
      <div style={{ position: "absolute", left: 760, top: 260, width: 560, height: 350, borderRadius: 34, background: "linear-gradient(135deg, #1c2a23, #0b1510)", border: `2px solid ${debt > 0.5 ? "rgba(224,75,75,0.7)" : "rgba(255,255,255,0.25)"}`, boxShadow: `0 0 70px ${debt > 0.5 ? RED_GLOW : "rgba(255,255,255,0.12)"}`, padding: 40, opacity: k(t, v(14.6), 0.3), transform: `translateY(${((1 - cardE) * 80).toFixed(1)}px) rotate(${(-4 + 2 * cardE).toFixed(2)}deg)` }}>
        <div style={{ width: 86, height: 64, borderRadius: 12, background: "linear-gradient(135deg, #e8e2c4, #9d977a)" }} />
        <div style={{ marginTop: 70, fontFamily: FONT, fontSize: 44, letterSpacing: "0.16em", color: TEXT }}>•••• •••• •••• 2026</div>
        <div style={{ marginTop: 24, fontFamily: FONT, fontSize: 26, color: SOFT, letterSpacing: "0.12em" }}>CRÉDITO</div>
      </div>
      {/* fatura */}
      <div style={{ position: "absolute", left: 1380, top: 250, width: 380, opacity: k(t, v(15.4), 0.4) }}>
        <div style={{ fontFamily: FONT, fontSize: 28, color: SOFT, letterSpacing: "0.12em" }}>FATURA</div>
        <div style={{ fontFamily: FONT, fontWeight: 700, fontSize: 84, letterSpacing: "-0.04em", color: debt > 0.5 ? RED : TEXT, textShadow: debt > 0.5 ? `0 0 30px ${RED_GLOW}` : undefined, fontVariantNumeric: "tabular-nums" }}>R$ {valor.toLocaleString("pt-BR")}</div>
        <div style={{ marginTop: 18, height: 26, borderRadius: 13, background: "rgba(255,255,255,0.08)", overflow: "hidden" }}>
          <div style={{ width: `${(20 + 80 * grow).toFixed(1)}%`, height: "100%", borderRadius: 13, background: debt > 0.5 ? RED : BTN, boxShadow: `0 0 20px ${debt > 0.5 ? RED_GLOW : "rgba(63,220,126,0.4)"}` }} />
        </div>
        <div style={{ marginTop: 34 }}><Chip t={t} at={20.62} bg="rgba(224,75,75,0.12)" border="rgba(224,75,75,0.5)" color="#ff9b9b" size={28}>juros mais caros do mercado</Chip></div>
      </div>
      <div style={{ position: "absolute", left: 760, top: 680, width: 1000, opacity: debt }}>
        <Txt t={t} at={19.3} size={46} color={SOFT} weight={400}>o aperto vira <span style={{ color: RED, fontWeight: 600 }}>dívida</span></Txt>
      </div>
    </AbsoluteFill>
  );
};

// ───────── 4. o plano de 30 dias (22,9–41,4 s) ─────────
const WEEKS: [string, string, string, number][] = [
  ["Semana 1", "Enxergar", "pra onde o seu dinheiro vaza", 28.48],
  ["Semana 2", "Estancar", "sair dos juros mais caros", 32.4],
  ["Semana 3", "Separar", "guardar vira automático", 35.34],
  ["Semana 4", "Proteger", "sua meta e o caminho", 38.12],
];
const Plano: React.FC<{ t: number }> = ({ t }) => {
  const s = t - VO;
  const cur = WEEKS.reduce((acc, w, i) => (s >= w[3] - 0.1 ? i : acc), -1);
  return (
    <AbsoluteFill>
      <div style={{ position: "absolute", left: 250, top: 70 }}>
        <Phone t={t} at={23.1} src={tela("hoje.png")} w={360} tilt={-2} />
      </div>
      <div style={{ position: "absolute", left: 760, top: 80, display: "flex", flexDirection: "column", gap: 18 }}>
        <div style={{ opacity: k(t, v(23.38), 0.4) }}><Logo size={64} /></div>
        <Txt t={t} at={24.18} size={66}>um plano de <span style={{ color: BRIGHT }}>30 dias</span> no celular</Txt>
        <div style={{ display: "flex", gap: 16 }}>
          <Chip t={t} at={26.46} size={28}>1 tarefa por dia</Chip>
          <Chip t={t} at={27.34} size={28} bg="rgba(63,220,126,0.12)" border="rgba(63,220,126,0.5)" color={BRIGHT}>10 minutos</Chip>
        </div>
      </div>
      <div style={{ position: "absolute", left: 760, top: 400, width: 980, display: "flex", flexDirection: "column", gap: 14 }}>
        {WEEKS.map(([n, name, desc, at], i) => {
          const e = k(t, v(at) - 0.1, 0.5);
          const on = cur === i;
          return (
            <div key={n} style={{ display: "flex", alignItems: "center", gap: 26, height: 100, padding: "0 30px", borderRadius: 26, background: on ? "rgba(63,220,126,0.12)" : CARD, border: `1px solid ${on ? "rgba(63,220,126,0.6)" : LINE}`, boxShadow: on ? "0 0 40px rgba(63,220,126,0.18)" : "none", opacity: e, transform: `translateX(${((1 - e) * 60).toFixed(1)}px)` }}>
              <span style={{ display: "grid", placeItems: "center", width: 54, height: 54, borderRadius: 999, background: on || cur > i ? BTN : "rgba(255,255,255,0.08)", color: "#fff", fontFamily: FONT, fontWeight: 700, fontSize: 26 }}>{cur > i ? "✓" : i + 1}</span>
              <span style={{ fontFamily: FONT, fontSize: 26, color: SOFT, width: 140 }}>{n}</span>
              <span style={{ fontFamily: FONT, fontWeight: 600, fontSize: 42, color: on ? BRIGHT : TEXT, width: 230 }}>{name}</span>
              <span style={{ fontFamily: FONT, fontSize: 30, color: on ? TEXT : SOFT }}>{desc}</span>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

// ───────── 5. ferramentas do app (41,4–49,2 s) ─────────
const TOOLS: [string, string, number][] = [
  ["reserva.png", "Calculadora da reserva", 42.04],
  ["dividas.png", "Roteiro pra renegociar", 43.6],
  ["sos.png", "SOS da vontade de gastar", 46.7],
];
const Ferramentas: React.FC<{ t: number }> = ({ t }) => {
  const s = t - VO;
  return (
    <AbsoluteFill>
      <div style={{ position: "absolute", left: 0, right: 0, top: 70, display: "flex", justifyContent: "center", gap: 90 }}>
        {TOOLS.map(([f, label, at], i) => {
          const focus = s >= at - 0.1 && (i === TOOLS.length - 1 || s < TOOLS[i + 1][2] - 0.1);
          return (
            <div key={f} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 22 }}>
              <Phone t={t} at={41.45 + i * 0.14} src={tela(f)} w={320} tilt={(i - 1) * 2} dim={focus ? 0 : 0.6} />
              <div>
                <Chip t={t} at={41.6 + i * 0.14} size={28} bg={focus ? "rgba(63,220,126,0.14)" : CARD} border={focus ? "rgba(63,220,126,0.6)" : LINE} color={focus ? BRIGHT : TEXT}>{label}</Chip>
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

// ───────── 6a. não é investimento: é organizar o que você já ganha (49,2–57 s) ─────────
const Strike: React.FC<{ t: number; at: number; strikeAt: number; children: React.ReactNode }> = ({ t, at, strikeAt, children }) => (
  <div style={{ position: "relative", display: "inline-block", padding: "16px 34px", borderRadius: 999, border: `1px solid ${LINE}`, background: CARD, fontFamily: FONT, fontWeight: 600, fontSize: 40, color: SOFT, opacity: k(t, v(at), 0.3) * (1 - 0.45 * k(t, v(strikeAt) + 0.3, 0.5)) }}>
    {children}
