import React from "react";

// Boneco do Rumo Fora: manequim liso, sem rosto, em preto e branco com brilho suave (a "assinatura" das animações próprias).
// Desenhado de perfil em coordenadas locais: origem nos pés, 200 unidades de altura, y para cima é negativo.
// Membros do lado de trás saem mais escuros para dar profundidade; o corpo tem degradê vertical e halo branco.

export type Pose = {
  armF?: number; // ângulo do braço da frente (graus, 0 = para baixo, positivo = para a frente)
  armB?: number;
  elbowF?: number; // dobra do cotovelo (positivo = antebraço sobe para a frente)
  elbowB?: number;
  legF?: number; // ângulo da coxa (positivo = para a frente)
  legB?: number;
  kneeF?: number; // dobra do joelho (positivo = canela vai para trás)
  kneeB?: number;
  lean?: number; // inclinação do tronco
  head?: number; // inclinação da cabeça
};

const rad = (d: number) => (d * Math.PI) / 180;
// ponto no fim de um segmento que parte de (x, y) com ângulo a partir da vertical para baixo
const seg = (x: number, y: number, len: number, deg: number) => [x + Math.sin(rad(deg)) * len, y + Math.cos(rad(deg)) * len] as const;

// ciclo de caminhada (fase em ciclos; 1 ciclo = 2 passos)
export const walk = (phase: number, amp = 1): Pose => {
  const p = phase * Math.PI * 2;
  const s = Math.sin(p);
  return {
    legF: 24 * s * amp,
    legB: -24 * s * amp,
    kneeF: Math.max(0, 38 * Math.sin(p - 1.2)) * amp + 4,
    kneeB: Math.max(0, 38 * Math.sin(p + Math.PI - 1.2)) * amp + 4,
    armF: -20 * s * amp,
    armB: 20 * s * amp,
    elbowF: 14 + 8 * Math.max(0, -s) * amp,
    elbowB: 14 + 8 * Math.max(0, s) * amp,
    lean: 3 * amp,
  };
};
// respiração parada (nunca fica estático)
export const idle = (t: number, seed = 0): Pose => ({
  armF: 4 + Math.sin(t * 1.6 + seed) * 2,
  armB: -3 + Math.sin(t * 1.6 + seed + 1) * 2,
  elbowF: 8,
  elbowB: 8,
  legF: 3,
  legB: -3,
  kneeF: 2,
  kneeB: 2,
  head: Math.sin(t * 0.9 + seed) * 3,
});
export const mix = (a: Pose, b: Pose, p: number): Pose => {
  const keys = new Set([...Object.keys(a), ...Object.keys(b)]) as Set<keyof Pose>;
  const o: Pose = {};
  keys.forEach((key) => {
    o[key] = (a[key] ?? 0) + ((b[key] ?? 0) - (a[key] ?? 0)) * p;
  });
  return o;
};

type Prop = "mala" | "passaporte" | "celular" | null;

export const Boneco: React.FC<{
  x: number; // posição dos pés na tela (px)
  y: number;
  h?: number; // altura em px
  pose?: Pose;
  flip?: boolean; // olhando para a esquerda
  prop?: Prop;
  glow?: number; // 0..1
  opacity?: number;
  id: string; // único por boneco (degradês do SVG)
  tone?: number; // 1 = branco, menor = mais cinza (figuras ao fundo)
}> = ({ x, y, h = 420, pose = {}, flip, prop = null, glow = 1, opacity = 1, id, tone = 1 }) => {
  const P = { armF: 0, armB: 0, elbowF: 0, elbowB: 0, legF: 0, legB: 0, kneeF: 0, kneeB: 0, lean: 0, head: 0, ...pose };
  const hip = [0, -94] as const;
  // tronco inclinado em torno do quadril
  const sh = seg(hip[0], hip[1], -58, -P.lean); // ombro (segmento para cima)
  const neck = seg(sh[0], sh[1], -12, -P.lean);
  const headC = seg(neck[0], neck[1], -17, -P.lean - P.head);
  // pernas: coxa e canela (o joelho dobra para trás)
  const knee = (a: number) => seg(hip[0], hip[1], 47, a);
  const foot = (a: number, k: number) => {
    const kn = knee(a);
    return seg(kn[0], kn[1], 47, a - k);
  };
  const elbow = (a: number) => seg(sh[0], sh[1], 36, a);
  const hand = (a: number, e: number) => {
    const el = elbow(a);
    return seg(el[0], el[1], 33, a + e);
  };
  const kF = knee(P.legF), fF = foot(P.legF, P.kneeF);
  const kB = knee(P.legB), fB = foot(P.legB, P.kneeB);
  const eF = elbow(P.armF), hF = hand(P.armF, P.elbowF);
  const eB = elbow(P.armB), hB = hand(P.armB, P.elbowB);
  const hi = Math.round(242 * tone), lo = Math.round(150 * tone), back = Math.round(105 * tone);
  const c = (n: number) => `rgb(${n},${n},${n})`;
  const g = `bn-${id}`;
  const limb = (pts: readonly (readonly [number, number])[], w: number, stroke: string) => (
    <polyline points={pts.map((q) => q.join(",")).join(" ")} fill="none" stroke={stroke} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" />
  );
  // pé: pequena cápsula apontando para a frente
  const feet = (f: readonly [number, number], stroke: string) => <line x1={f[0] - 3} y1={f[1] - 3} x2={f[0] + 11} y2={f[1] - 3} stroke={stroke} strokeWidth={10} strokeLinecap="round" />;
  const torso = (() => {
    // silhueta: largura ao longo do eixo quadril → ombro (ombro largo, cintura fina, quadril médio)
    const ax = sh[0] - hip[0], ay = sh[1] - hip[1];
    const nx = Math.cos(rad(P.lean)), ny = Math.sin(rad(P.lean));
    const W: [number, number][] = [[0, 15], [0.18, 13.5], [0.42, 12], [0.7, 16], [0.9, 19], [1, 17]];
    const pt = (f: number, w: number, side: number) => [hip[0] + ax * f + nx * w * side, hip[1] + ay * f + ny * w * side].map((n) => n.toFixed(1)).join(" ");
    const right = W.map(([f, w]) => pt(f, w * 1.05, 1));
    const left = [...W].reverse().map(([f, w]) => pt(f, w * 0.95, -1));
    return `M${right[0]} L${right.slice(1).join(" L")} L${left.join(" L")} Z`;
  })();
  const blur = 10 * glow, blur2 = 34 * glow;
  return (
    <svg
      width={h * 1.4}
      height={h * 1.3}
      viewBox={`-140 -240 280 260`}
      style={{
        position: "absolute",
        left: x - h * 0.7,
        top: y - h * 1.3 * (240 / 260),
        overflow: "visible",
        opacity,
        transform: flip ? "scaleX(-1)" : undefined,
        filter: glow > 0 ? `drop-shadow(0 0 ${blur.toFixed(1)}px rgba(255,255,255,${(0.45 * glow).toFixed(2)})) drop-shadow(0 0 ${blur2.toFixed(1)}px rgba(255,255,255,${(0.18 * glow).toFixed(2)}))` : undefined,
      }}
    >
      <defs>
        <linearGradient id={g} gradientUnits="userSpaceOnUse" x1="0" y1="-210" x2="0" y2="0">
          <stop offset="0" stopColor={c(hi)} />
          <stop offset="1" stopColor={c(lo)} />
        </linearGradient>
        <radialGradient id={`${g}-h`} cx="0.38" cy="0.32" r="0.75">
          <stop offset="0" stopColor="#ffffff" />
          <stop offset="1" stopColor={c(Math.round(190 * tone))} />
        </radialGradient>
      </defs>
      {/* sombra no chão */}
      <ellipse cx={4} cy={1} rx={34} ry={5} fill="rgba(255,255,255,0.10)" />
      {/* lado de trás */}
      {limb([hip, kB, fB], 15, c(back))}
      {feet(fB, c(back))}
      {limb([sh, eB, hB], 11, c(back))}
      {/* corpo */}
      <path d={torso} fill={`url(#${g})`} stroke={`url(#${g})`} strokeWidth={7} strokeLinejoin="round" />
      <line x1={sh[0]} y1={sh[1]} x2={neck[0]} y2={neck[1]} stroke={`url(#${g})`} strokeWidth={10} strokeLinecap="round" />
      <ellipse cx={headC[0]} cy={headC[1]} rx={15} ry={17} fill={`url(#${g}-h)`} transform={`rotate(${P.lean + P.head} ${headC[0]} ${headC[1]})`} />
      {/* lado da frente */}
      {limb([hip, kF, fF], 19, "rgba(0,0,0,0.35)")}
      {limb([hip, kF, fF], 15, `url(#${g})`)}
      {feet(fF, c(lo))}
      {prop === "mala" && <Mala x={hF[0]} y={hF[1]} tone={tone} />}
      {limb([sh, eF, hF], 15, "rgba(0,0,0,0.4)")}
      {limb([sh, eF, hF], 11, `url(#${g})`)}
      {prop === "passaporte" && <rect x={hF[0] - 2} y={hF[1] - 20} width={18} height={25} rx={2.5} fill="#ffffff" transform={`rotate(-12 ${hF[0]} ${hF[1]})`} />}
      {prop === "celular" && <rect x={hF[0] - 3} y={hF[1] - 22} width={12} height={22} rx={3} fill="#ffffff" transform={`rotate(-20 ${hF[0]} ${hF[1]})`} />}
    </svg>
  );
};

