import { MAP_SHAPES, WORLD_BOUNDS } from "./map-paths";

// Rumo Fora — "48 horas depois da eleição": motion vertical 1080×1920, 30 fps, ~37 s.
// Identidade do site (rumo-fora.vercel.app): fundo #0d0d0d com brilho suave no alto, Space Grotesk, monocromático;
// verde só para a marca e o Brasil, vermelho para quedas. Fotos reais com licença livre (créditos na tela e no fecho).
// Cada palavra surge no instante em que é dita (segundos da locução, audio/rumo-fora-vo.wav, voz Roger). Sem áudio aqui:
// a mixagem é feita à parte (tools/make_audio_rumofora.py + ffmpeg).

export const { fontFamily: FONT } = loadFont("normal", { weights: ["400", "500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const RF_FPS = 30;
const VO = 0.3; // a voz entra em 0,3 s
export const RF_FRAMES = Math.round(51.4 * RF_FPS);

export const PAPER = "#0d0d0d";
export const INK = "#f2f2f2";
export const MUTED = "#a3a3a3";
export const FAINT = "#6e6e6e";
export const GREEN = "#5ccf98";
export const GREEN_DEEP = "#15291f";
export const RED = "#ff8f86";
export const asset = (f: string) => staticFile(`rumo-fora/${f}`);

export const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
export const OUT = Easing.bezier(0.16, 1, 0.3, 1);
export const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
export const BACK = Easing.out(Easing.back(1.4));
export const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
export const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN_OUT });
export const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const v = (s: number) => s + VO; // segundo da locução → segundo do vídeo

// ───────── cenas: janela [início, fim] em segundos da locução ─────────
const SCENES = {
  horas: [-0.3, 2.45],
  mundo: [2.45, 4.62],
  lula: [4.62, 6.62],
  bolsa: [6.62, 12.95],
  acoes: [12.95, 15.95],
  dolar: [15.95, 20.25],
  flavio: [20.25, 24.75],
  falas: [24.75, 29.75],
  buscas: [29.9, 36.9],
  site: [36.9, 44.35],
  gratis: [44.35, 46.25],
  cta: [46.25, 99],
} as const;
type SceneKey = keyof typeof SCENES;
// visibilidade: entra com desfoque/escala e sai do mesmo jeito (corte limpo, 0,28 s)
const vis = (t: number, s: SceneKey) => {
  const [a, b] = SCENES[s];
  return io(t, v(a) - 0.14, 0.28) * (1 - io(t, v(b) - 0.14, 0.28));
};
const Scene: React.FC<{ t: number; s: SceneKey; children: React.ReactNode }> = ({ t, s, children }) => {
  const o = vis(t, s);
  if (o <= 0.001) return null;
  const [a] = SCENES[s];
  const el = Math.max(0, t - v(a));
  const drift = 1 + 0.08 * Math.min(1, el / 6); // a câmera nunca para: aproxima devagar, sempre no mesmo sentido
  const lift = -20 * Math.min(1, el / 6);
  return (
    <AbsoluteFill style={{ opacity: o, filter: o < 1 ? `blur(${((1 - o) * 14).toFixed(1)}px)` : undefined, transform: `translateY(${lift.toFixed(1)}px) scale(${((0.94 + 0.06 * o) * drift).toFixed(4)})` }}>
      {children}
    </AbsoluteFill>
  );
};

// ───────── texto: palavras no tempo da fala ─────────
export type W = [string, number, ("g" | "r")?]; // [palavra, segundo da locução, destaque verde/vermelho]
export const Say: React.FC<{ t: number; words: W[]; size: number; color?: string; weight?: number }> = ({ t, words, size, color = INK, weight = 500 }) => (
  <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", columnGap: size * 0.26, rowGap: size * 0.02, fontFamily: FONT, fontWeight: weight, fontSize: size, lineHeight: 1.08, letterSpacing: "-0.035em", color, textAlign: "center", maxWidth: 960 }}>
    {words.map(([w, at, em], i) => {
      const e = k(t, v(at) - 0.06, 0.4);
      return (
        <span key={i} style={{ display: "inline-block", opacity: k(t, v(at) - 0.06, 0.16), filter: e < 1 ? `blur(${((1 - e) * 10).toFixed(1)}px)` : undefined, transform: `translateY(${((1 - e) * size * 0.28).toFixed(1)}px)`, color: em === "g" ? GREEN : em === "r" ? RED : undefined }}>
          {w}
        </span>
      );
    })}
  </div>
);
export const Col: React.FC<{ top: number; gap?: number; children: React.ReactNode }> = ({ top, gap = 10, children }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap }}>{children}</div>
);
export const Eyebrow: React.FC<{ t: number; at: number; children: React.ReactNode; color?: string }> = ({ t, at, children, color = FAINT }) => (
  <div style={{ fontFamily: FONT, fontWeight: 500, fontSize: 30, letterSpacing: "0.22em", textTransform: "uppercase", color, opacity: k(t, v(at), 0.4), transform: `translateY(${(1 - k(t, v(at), 0.5)) * 14}px)` }}>{children}</div>
);
export const Pill: React.FC<{ t: number; at: number; bg: string; color?: string; size?: number; children: React.ReactNode }> = ({ t, at, bg, color = PAPER, size = 34, children }) => (
  <div style={{ display: "inline-flex", alignItems: "center", gap: size * 0.4, padding: `${size * 0.34}px ${size * 0.7}px`, borderRadius: 999, background: bg, color, fontFamily: FONT, fontWeight: 600, fontSize: size, letterSpacing: "-0.01em", transform: `scale(${(0.6 + 0.4 * pop(t, v(at), 0.5)).toFixed(3)})`, opacity: k(t, v(at), 0.2) }}>{children}</div>
);
// número que conta até o valor (formato brasileiro)
const count = (t: number, a: number, d: number, from: number, to: number) => from + (to - from) * io(t, v(a), d);
export const br = (n: number, dec = 2) => n.toLocaleString("pt-BR", { minimumFractionDigits: dec, maximumFractionDigits: dec });

// ───────── fundo contínuo: preto, brilho no alto, grade de pontos ─────────
export const Backdrop: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: PAPER }}>
    <AbsoluteFill style={{ background: `radial-gradient(900px 620px at ${50 + Math.sin(t * 0.35) * 22}% ${-120 + Math.sin(t * 0.5) * 60}px, rgba(255,255,255,0.11), transparent 70%)` }} />
    <AbsoluteFill style={{ background: `radial-gradient(700px 520px at ${50 - Math.sin(t * 0.3) * 30}% ${1900 + Math.cos(t * 0.4) * 60}px, rgba(92,207,152,0.06), transparent 70%)` }} />
    <AbsoluteFill style={{ backgroundImage: "radial-gradient(rgba(255,255,255,0.09) 1.4px, transparent 1.4px)", backgroundSize: "34px 34px", backgroundPosition: `${(Math.sin(t * 0.5) * 12).toFixed(1)}px ${(-t * 34).toFixed(1)}px`, opacity: 0.7 }} />
  </AbsoluteFill>
);

// ───────── marca: símbolo do Rumo Fora (quadrado branco, seta curva) ─────────
export const Symbol: React.FC<{ size: number; draw?: number; scale?: number }> = ({ size, draw = 1, scale = 1 }) => (
  <svg width={size} height={size} viewBox="0 0 32 32" style={{ overflow: "visible", transform: `scale(${scale})` }}>
    <rect width="32" height="32" rx="9" fill="#ffffff" />
    <g transform="translate(5.2 5.2) scale(0.9)" fill="none" stroke="#000" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round">
      <path d="M4 17c3-6 7-9 16-11" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - draw} />
      <path d="M15 5.5 20 6l-1.5 4.8" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - Math.max(0, draw * 2 - 1)} />
      <circle cx="5" cy="18" r={1.9 * Math.min(1, draw * 3)} fill="#000" stroke="none" />
    </g>
  </svg>
);

// cartão de foto (vidro escuro, borda fina) com crédito obrigatório
export const PhotoCard: React.FC<{ t: number; at: number; src: string; w: number; h: number; credit: string; pos?: string; tilt?: number; children?: React.ReactNode }> = ({ t, at, src, w, h, credit, pos = "50% 30%", tilt = 0, children }) => {
  const e = k(t, v(at) - 0.1, 0.7);
  return (
    <div style={{ position: "relative", width: w, height: h, borderRadius: 40, padding: 10, background: "rgba(255,255,255,0.06)", border: "1px solid rgba(255,255,255,0.14)", boxShadow: "0 40px 90px -30px rgba(0,0,0,0.9)", opacity: k(t, v(at) - 0.1, 0.3), transform: `translateY(${((1 - e) * 80).toFixed(1)}px) rotate(${((1 - e) * tilt * 2 + tilt).toFixed(2)}deg) scale(${(0.9 + 0.1 * e).toFixed(3)})` }}>
      <div style={{ position: "relative", width: "100%", height: "100%", borderRadius: 32, overflow: "hidden" }}>
        <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, transform: `scale(${(1.16 - 0.12 * Math.min(1, Math.max(0, t - v(at)) / 4)).toFixed(4)}) translateY(${(Math.min(1, Math.max(0, t - v(at)) / 4) * -14).toFixed(1)}px)` }} />
        <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, transparent 55%, rgba(0,0,0,0.65))" }} />
        <div style={{ position: "absolute", right: 18, bottom: 14, fontFamily: FONT, fontSize: 18, color: "rgba(255,255,255,0.75)", letterSpacing: "0.01em" }}>{credit}</div>
        {children}
      </div>
    </div>
  );
};

// ───────── mapa (mesma projeção do site) ─────────
export type View = [number, number, number, number];
export const lerpView = (a: View, b: View, p: number): View => [0, 1, 2, 3].map((i) => a[i] + (b[i] - a[i]) * p) as View;
const P = { brasilia: [620, 335], saopaulo: [633, 417], miami: [300, -88], washington: [331, -243], londres: [1094, -421], paris: [1118, -380], madri: [1058, -262], pequim: [2249, -256], buenosaires: [516, 543], assuncao: [524, 435], montevideu: [538, 546] } as const;
export const MapLayer: React.FC<{ view: View; brazilGlow?: number; children?: React.ReactNode; highlight?: string[] }> = ({ view, brazilGlow = 0.6, children, highlight = [] }) => (
  <svg viewBox={view.join(" ")} preserveAspectRatio="xMidYMid slice" style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }}>
    <image href={asset("mapa-mundi.svg")} x={WORLD_BOUNDS.x} y={WORLD_BOUNDS.y} width={WORLD_BOUNDS.width} height={WORLD_BOUNDS.height} preserveAspectRatio="none" opacity={0.55} />
    {MAP_SHAPES.map((s) => {
      const isBr = s.slug === "brasil";
      const on = highlight.includes(s.slug);
      return <path key={s.slug} d={s.d} fill={isBr ? GREEN_DEEP : on ? "#d4d4d4" : "#2a2a2a"} fillOpacity={isBr || on ? 1 : 0.55} stroke={isBr ? GREEN : on ? "#ffffff" : "#3a3a3a"} strokeWidth={isBr ? 1.6 : on ? 1.2 : 0.6} style={isBr ? { filter: `drop-shadow(0 0 ${(10 * brazilGlow).toFixed(1)}px rgba(92,207,152,${(0.5 * brazilGlow).toFixed(2)}))` } : undefined} />;
    })}
    {children}
  </svg>
);
// coordenada do mapa → pixel da tela (o SVG usa "slice" em 1080×1920), para etiquetas HTML de tamanho fixo
export const toScreen = (view: View, x: number, y: number) => {
  const sc = Math.max(1080 / view[2], 1920 / view[3]);
  return [540 + (x - (view[0] + view[2] / 2)) * sc, 960 + (y - (view[1] + view[3] / 2)) * sc] as const;
};
export const Tag: React.FC<{ x: number; y: number; o: number; dx?: number; dy?: number; light?: boolean; children: React.ReactNode }> = ({ x, y, o, dx = 0, dy = -70, light, children }) => (
  <div style={{ position: "absolute", left: x + dx, top: y + dy, transform: `translate(-50%, -50%) scale(${(0.8 + 0.2 * o).toFixed(3)})`, opacity: o, whiteSpace: "nowrap", padding: "14px 26px", borderRadius: 999, background: light ? "#ffffff" : "rgba(13,13,13,0.92)", color: light ? PAPER : INK, border: light ? "none" : "1px solid rgba(255,255,255,0.28)", fontFamily: FONT, fontWeight: 600, fontSize: 36 }}>{children}</div>
);

// ponto que pulsa (manchete acendendo)
export const Ping: React.FC<{ t: number; at: number; x: number; y: number; r: number; color?: string }> = ({ t, at, x, y, r, color = INK }) => {
  if (t < v(at) - 0.05) return null;
  const p = ((t - v(at)) % 1.4) / 1.4;
  return (
    <g>
      <circle cx={x} cy={y} r={r * (1 + p * 3)} fill="none" stroke={color} strokeWidth={r * 0.25} opacity={0.8 * (1 - p)} />
      <circle cx={x} cy={y} r={r * pop(t, v(at), 0.4)} fill={color} />
    </g>
  );
};

// ───────── 1. 48 horas ─────────
const Horas: React.FC<{ t: number }> = ({ t }) => {
  const sweep = io(t, v(0.35), 1.6);
  const n = Math.round(count(t, 0.35, 0.9, 0, 48));
  return (
    <AbsoluteFill>
      <Col top={360} gap={40}>
        <div style={{ opacity: k(t, 0.1, 0.4), transform: `scale(${(0.7 + 0.3 * pop(t, 0.1, 0.6)).toFixed(3)})` }}><Symbol size={120} draw={io(t, 0.15, 0.9)} /></div>
        <div style={{ position: "relative", width: 520, height: 520 }}>
          <svg viewBox="0 0 520 520" style={{ position: "absolute", inset: 0 }}>
            <circle cx="260" cy="260" r="236" fill="none" stroke="rgba(255,255,255,0.1)" strokeWidth="4" />
            <circle cx="260" cy="260" r="236" fill="none" stroke={INK} strokeWidth="6" strokeLinecap="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - sweep} transform="rotate(-90 260 260)" />
            {Array.from({ length: 48 }, (_, i) => {
              const a = (i / 48) * Math.PI * 2;
              const on = i / 48 <= sweep;
              return <line key={i} x1={260 + Math.sin(a) * 206} y1={260 - Math.cos(a) * 206} x2={260 + Math.sin(a) * (i % 12 === 0 ? 186 : 196)} y2={260 - Math.cos(a) * (i % 12 === 0 ? 186 : 196)} stroke={on ? INK : "rgba(255,255,255,0.18)"} strokeWidth={i % 12 === 0 ? 4 : 2} strokeLinecap="round" />;
            })}
          </svg>
          <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", fontFamily: FONT, color: INK }}>
            <div style={{ fontSize: 210, fontWeight: 600, letterSpacing: "-0.06em", lineHeight: 1, fontVariantNumeric: "tabular-nums" }}>{n}</div>
            <div style={{ fontSize: 46, fontWeight: 500, color: MUTED, opacity: k(t, v(0.87), 0.3) }}>horas</div>
          </div>
        </div>
        <Say t={t} size={78} words={[["depois", 1.21], ["da", 1.61], ["eleição", 1.75]]} />
      </Col>
    </AbsoluteFill>
  );
};

// ───────── 2. o Brasil virou manchete no mundo ─────────
const OUTLETS: [string, number, number, number, number, number][] = [ // [veículo, x, y, segundo, deslocamento x/y da etiqueta]
  ["Reuters", P.washington[0], P.washington[1], 3.09, 0, -70],
  ["The New York Times", P.miami[0], P.miami[1], 3.4, 60, 70],
  ["BBC", P.londres[0], P.londres[1], 3.7, 0, -70],
  ["El País", P.madri[0], P.madri[1], 3.98, -10, 70],
];
const Mundo: React.FC<{ t: number }> = ({ t }) => {
  const view = lerpView([20, -1150, 1380, 2453], [120, -1000, 1180, 2098], io(t, v(2.45), 2.2));
  return (
    <AbsoluteFill>
      <MapLayer view={view} brazilGlow={0.6 + 0.4 * Math.sin(t * 4)}>
        <Ping t={t} at={2.63} x={P.brasilia[0]} y={P.brasilia[1]} r={14} color={GREEN} />
        {OUTLETS.map(([, x, y, at], i) => <Ping key={i} t={t} at={at} x={x} y={y} r={14} />)}
      </MapLayer>
      {OUTLETS.map(([name, x, y, at, dx, dy], i) => {
        const [sx, sy] = toScreen(view, x, y);
        return <Tag key={i} x={sx} y={sy} dx={dx} dy={dy} o={k(t, v(at), 0.3)}>{name}</Tag>;
      })}
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(13,13,13,0.95) 0%, rgba(13,13,13,0) 34%, rgba(13,13,13,0) 70%, rgba(13,13,13,0.9) 100%)" }} />
      <Col top={210}>
        <Say t={t} size={84} words={[["o", 2.55], ["Brasil", 2.63, "g"], ["virou", 3.09]]} />
        <Say t={t} size={84} words={[["manchete", 3.39], ["no", 3.98], ["mundo", 4.12]]} />
      </Col>
    </AbsoluteFill>
  );
};

