const Bolsa: React.FC<{ t: number }> = ({ t }) => {
  const draw = io(t, v(7.5), 1.9);
  const pct = count(t, 7.98, 1.4, 0, -13.88);
  const halt = k(t, v(12.0), 0.5);
  const W = 900, H = 420;
  const pts = CHART.map((y, i) => [(i / (CHART.length - 1)) * W, (-y / 14) * H] as const);
  const n = Math.max(2, Math.ceil(draw * pts.length));
