        <Say t={t} size={80} words={[["despencou", 7.98, "r"]]} />
      </Col>
      <div style={{ position: "absolute", left: 90, top: 640, width: W, height: H }}>
        <svg width={W} height={H + 40} style={{ overflow: "visible" }}>
