        <div style={{ fontFamily: FONT, fontWeight: 600, fontSize: 220, letterSpacing: "-0.06em", color: RED, lineHeight: 1, fontVariantNumeric: "tabular-nums", opacity: k(t, v(7.98), 0.3), transform: `scale(${(1 + 0.08 * (1 - k(t, v(9.06), 0.5)) * (t > v(9.06) ? 1 : 0)).toFixed(3)})` }}>{br(pct)}%</div>
        <Say t={t} size={50} color={MUTED} weight={400} words={[["e", 10.42], ["as", 10.52], ["negociações", 10.66], ["chegaram", 11.32], ["a", 11.72], ["ser", 11.82], ["interrompidas", 12.0, "r"]]} />
        <div style={{ opacity: halt, transform: `scale(${(0.7 + 0.3 * pop(t, v(12.0), 0.5)).toFixed(3)})`, display: "flex", alignItems: "center", gap: 18, padding: "18px 34px", borderRadius: 999, border: `2px solid ${RED}`, color: RED, fontFamily: FONT, fontWeight: 600, fontSize: 34, letterSpacing: "0.08em" }}>
