};

// ───────── 5. ações caíram até 58% ─────────
const BARS = [0.34, 0.47, 0.58, 0.41, 0.52, 0.29, 0.44];
const Acoes: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill>
    <Col top={300}>
