// traço fino que atravessa a tela nas trocas de assunto (o "rumo" da marca)
export const Sweep: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  const p = io(t, v(at) - 0.3, 0.6);
  if (p <= 0 || p >= 1) return null;
