import { AbsoluteFill, Img, OffthreadVideo, Sequence, staticFile, useCurrentFrame } from "remotion";
import { FONT, io, k, pop } from "./RumoFora";

// Desaperto — anúncio "A eleição acabou" (versão A, política): selfie 9:16, 30 fps, ~38,8 s.
// Três blocos: vídeo A do Seedance (0–12,04 s) → motion com a parte 2 da voz (12,04–25,24 s) → vídeo B (25,24–37,28 s),
// com um B-roll do site no meio do vídeo B, e o cartão final. Identidade da página /desaperto: branco, tinta #10241a,
// verde profundo #0e4a2c, verde vivo #3fdc7e, botão #1f9d55, Space Grotesk. Legendas palavra a palavra (WhisperX).
// Som mixado à parte (ffmpeg): voz do vídeo A em 0 s, parte2.wav em M_START, voz do vídeo B em B_START.
// Tudo o que importa fica na área segura do Reels (≈ 290 a 1590 px na vertical).

export const DS_FPS = 30;
export const A_END = 12.04;
export const M_START = A_END;
export const M_IN = 9.9; // o motion entra antes do fim do vídeo A, em "presidente americano"
export const M_END = M_START + 13.2;
export const B_START = M_END;
export const B_END = B_START + 12.04;
export const END = B_END + 1.6;
export const DS_FRAMES = Math.round(END * DS_FPS);

export const WHITE = "#ffffff";
export const BG = "#f5faf7";
export const INK = "#10241a";
export const DEEP = "#0e4a2c";
export const BRIGHT = "#3fdc7e";
export const BTN = "#1f9d55";
export const RED = "#e04b4b";
export const MUTED = "#5b6b62";
export const a = (f: string) => staticFile(`desaperto/${f}`);

// ───────── legenda sobre o vídeo: frase atual, palavra dita acende em verde ─────────
export type Wd = [string, number, ("g" | "r")?];
export const Caption: React.FC<{ t: number; phrases: Wd[][]; top?: number; light?: boolean }> = ({ t, phrases, top = 1360, light }) => {
  const i = phrases.findIndex((p, j) => t >= p[0][1] - 0.08 && (j === phrases.length - 1 || t < phrases[j + 1][0][1] - 0.08));
  if (i < 0) return null;
  const p = phrases[i];
  return (
    <div style={{ position: "absolute", left: 70, right: 70, top, display: "flex", flexWrap: "wrap", justifyContent: "center", columnGap: 18, rowGap: 4 }}>
      {p.map(([w, at, em], j) => {
        const e = k(t, at - 0.06, 0.25);
        const next = p[j + 1]?.[1] ?? 99;
        const live = t >= at - 0.04 && t < next;
        return (
          <span key={j} style={{ fontFamily: FONT, fontWeight: 700, fontSize: 70, letterSpacing: "-0.03em", lineHeight: 1.1, color: em === "r" ? "#ff8f86" : live || em === "g" ? (light ? BTN : BRIGHT) : light ? INK : WHITE, opacity: e, transform: `translateY(${((1 - e) * 18).toFixed(1)}px) scale(${live ? 1.04 : 1})`, textShadow: light ? undefined : "0 4px 18px rgba(0,0,0,0.75), 0 0 2px rgba(0,0,0,0.9)" }}>
            {w}
          </span>
        );
      })}
    </div>
  );
};

// texto do motion: palavras surgem quando ditas (m = segundos da parte 2)
export const Say: React.FC<{ m: number; words: Wd[]; size: number; color?: string; weight?: number }> = ({ m, words, size, color = INK, weight = 600 }) => (
  <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", columnGap: size * 0.26, fontFamily: FONT, fontWeight: weight, fontSize: size, lineHeight: 1.08, letterSpacing: "-0.035em", color, maxWidth: 960 }}>
    {words.map(([w, at, em], i) => {
      const e = k(m, at - 0.06, 0.4);
      return <span key={i} style={{ display: "inline-block", opacity: k(m, at - 0.06, 0.16), filter: e < 1 ? `blur(${((1 - e) * 8).toFixed(1)}px)` : undefined, transform: `translateY(${((1 - e) * size * 0.28).toFixed(1)}px)`, color: em === "g" ? BTN : em === "r" ? RED : undefined }}>{w}</span>;
    })}
  </div>
);
export const Col: React.FC<{ top: number; gap?: number; children: React.ReactNode }> = ({ top, gap = 8, children }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap }}>{children}</div>
);

// marca do Desaperto (mesmo símbolo da página)
export const Logo: React.FC<{ size: number }> = ({ size }) => (
  <div style={{ display: "inline-flex", alignItems: "center", gap: size * 0.32 }}>
    <div style={{ width: size, height: size, borderRadius: size * 0.32, background: DEEP, display: "grid", placeItems: "center" }}>
      <svg viewBox="0 0 24 24" width={size * 0.6} height={size * 0.6} fill="none" stroke={BRIGHT} strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round"><path d="M5 9c2.5-3 11.5-3 14 0M5 15c2.5 3 11.5 3 14 0" /><path d="M12 6v12" /></svg>
    </div>
    <span style={{ fontFamily: FONT, fontSize: size * 0.62, letterSpacing: "-0.03em", color: INK }}><b style={{ fontWeight: 600 }}>des</b>aperto</span>
  </div>
);

export const Bg: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: BG }}>
    <AbsoluteFill style={{ background: `radial-gradient(800px 600px at ${50 + Math.sin(t * 0.4) * 20}% -80px, rgba(63,220,126,0.18), transparent 70%)` }} />
    <AbsoluteFill style={{ backgroundImage: "radial-gradient(rgba(14,74,44,0.10) 1.4px, transparent 1.4px)", backgroundSize: "34px 34px", backgroundPosition: `0px ${(-t * 30).toFixed(1)}px` }} />
  </AbsoluteFill>
);

export const Photo: React.FC<{ m: number; at: number; src: string; w: number; h: number; credit: string; pos?: string; tilt?: number }> = ({ m, at, src, w, h, credit, pos = "50% 50%", tilt = 0 }) => {
  const e = k(m, at - 0.1, 0.7);
  const el = Math.min(1, Math.max(0, m - at) / 4);
  return (
    <div style={{ position: "relative", width: w, height: h, borderRadius: 40, padding: 10, background: WHITE, boxShadow: "0 40px 80px -30px rgba(16,36,26,0.45)", opacity: k(m, at - 0.1, 0.3), transform: `translateY(${((1 - e) * 80).toFixed(1)}px) rotate(${((1 - e) * tilt * 2 + tilt).toFixed(2)}deg) scale(${(0.9 + 0.1 * e).toFixed(3)})` }}>
      <div style={{ position: "relative", width: "100%", height: "100%", borderRadius: 32, overflow: "hidden" }}>
        <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, transform: `scale(${(1.14 - 0.1 * el).toFixed(4)})` }} />
        <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, transparent 60%, rgba(0,0,0,0.55))" }} />
        <div style={{ position: "absolute", right: 18, bottom: 14, fontFamily: FONT, fontSize: 18, color: "rgba(255,255,255,0.85)" }}>{credit}</div>
      </div>
    </div>
  );
};

// cena do motion: entra e sai com desfoque, câmera aproximando devagar
export const Scene: React.FC<{ m: number; from: number; to: number; children: React.ReactNode }> = ({ m, from, to, children }) => {
  const o = io(m, from - 0.14, 0.28) * (1 - io(m, to - 0.14, 0.28));
  if (o <= 0.001) return null;
  const el = Math.min(1, Math.max(0, m - from) / 5);
  return <AbsoluteFill style={{ opacity: o, filter: o < 1 ? `blur(${((1 - o) * 12).toFixed(1)}px)` : undefined, transform: `translateY(${(-16 * el).toFixed(1)}px) scale(${((0.95 + 0.05 * o) * (1 + 0.05 * el)).toFixed(4)})` }}>{children}</AbsoluteFill>;
};

